public class VariableDemo {
    private static int staticCounter = 0; // Shared across all instances
    private final int instanceId;         // Unique to each object

    public VariableDemo(int id) {
        this.instanceId = id;
    }

    public void process(int input) {
        int localVar = input * 2; // Stack-allocated, thread-confined
        System.out.println("Instance: " + instanceId + ", Local: " + localVar);
    }
}
